import{_ as o,c as a,o as e,b0 as d}from"./chunks/framework.C5ev1SXp.js";const r="/scm-docs/assets/dhcp-dora.C048-Lag.svg",P=JSON.parse('{"title":"LV040-DHCP与IP地址自动获取","description":null,"frontmatter":{"title":"LV040-DHCP与IP地址自动获取","date":"2026-10-14T21:56:00.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/network-basics/126d628e1bb0326cce94ffc3","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-14T21:56:00.806Z","fulluuid":"cce94ffc348b427c8f67298cff2144b9","useduuid":"cce94ffc3"}},"headers":[],"relativePath":"sdoc/advanced-chapter/network-basics/126d628e1bb0326cce94ffc3.md","filePath":"sdoc/30-进阶篇/05-网络基础/LV040-DHCP与IP地址自动获取.md","lastUpdated":1792231946000}'),c={name:"sdoc/advanced-chapter/network-basics/126d628e1bb0326cce94ffc3.md"};function l(n,t,h,i,s,p){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="lv040-dhcp与ip地址自动获取" tabindex="-1">LV040-DHCP与IP地址自动获取 <a class="header-anchor" href="#lv040-dhcp与ip地址自动获取" aria-label="Permalink to &quot;LV040-DHCP与IP地址自动获取&quot;">​</a></h1><h2 id="一、-ip-地址的两种来源" tabindex="-1">一、 IP 地址的两种来源 <a class="header-anchor" href="#一、-ip-地址的两种来源" aria-label="Permalink to &quot;一、 IP 地址的两种来源&quot;">​</a></h2><h3 id="_1-静态配置与-dhcp" tabindex="-1">1. 静态配置与 DHCP <a class="header-anchor" href="#_1-静态配置与-dhcp" aria-label="Permalink to &quot;1. 静态配置与 DHCP&quot;">​</a></h3><p>设备刚接入网络时，它自己并不知道该用什么 IP。有两种做法：</p><table tabindex="0"><thead><tr><th>方式</th><th>谁决定地址</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>静态配置</td><td>人（写死或用命令行）</td><td>地址<strong>可预测</strong>，环境不受服务器影响</td><td>要手工维护，容易冲突或写错</td></tr><tr><td>DHCP 自动获取</td><td>网络里的 DHCP 服务器</td><td>即插即用，不冲突</td><td>依赖服务器；地址不固定</td></tr></tbody></table><p>家里的手机、电脑连 WiFi 都是第二种，所以从来不用配 IP；而<strong>本工程用的是第一种</strong>，地址写死在宏里。</p><h3 id="_2-两种方式的取舍" tabindex="-1">2. 两种方式的取舍 <a class="header-anchor" href="#_2-两种方式的取舍" aria-label="Permalink to &quot;2. 两种方式的取舍&quot;">​</a></h3><p>这两种方式没有优劣，只有&quot;适合什么场景&quot;：</p><ul><li><strong>静态配置适合&quot;地址必须被外部知道&quot;的场景</strong>。比如服务器、打印机、以及本工程的 Bootloader——PC 上的脚本得知道去连谁。</li><li><strong>DHCP 适合&quot;设备频繁加入离开、地址不必固定&quot;的场景</strong>。比如咖啡厅的 WiFi、办公室的访客网络。</li></ul><p>本工程选静态的完整理由见第五节。</p><h2 id="二、-dhcp-在协议栈里的位置" tabindex="-1">二、 DHCP 在协议栈里的位置 <a class="header-anchor" href="#二、-dhcp-在协议栈里的位置" aria-label="Permalink to &quot;二、 DHCP 在协议栈里的位置&quot;">​</a></h2><h3 id="_1-跑在-udp-上的应用层协议" tabindex="-1">1. 跑在 UDP 上的应用层协议 <a class="header-anchor" href="#_1-跑在-udp-上的应用层协议" aria-label="Permalink to &quot;1. 跑在 UDP 上的应用层协议&quot;">​</a></h3><p>DHCP（Dynamic Host Configuration Protocol，动态主机配置协议）本身是一个<strong>应用层协议</strong>，运行在 <strong>UDP</strong> 之上：</p><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>传输层协议</td><td>UDP</td></tr><tr><td>服务器端口</td><td>67</td></tr><tr><td>客户端端口</td><td>68</td></tr><tr><td>广播地址</td><td>255.255.255.255</td></tr></tbody></table><p>这里有个绕不开的循环：<strong>要靠 DHCP 拿 IP，可发 DHCP 报文本身又需要 IP</strong>。</p><h3 id="_2-先有鸡还是先有蛋-的绕法" tabindex="-1">2. &quot;先有鸡还是先有蛋&quot;的绕法 <a class="header-anchor" href="#_2-先有鸡还是先有蛋-的绕法" aria-label="Permalink to &quot;2. &quot;先有鸡还是先有蛋&quot;的绕法&quot;">​</a></h3><p>解决办法是用特殊地址把这一步绕过去：</p><ul><li>源 IP 用 <code>0.0.0.0</code>（&quot;我还没有地址&quot;）；</li><li>目的 IP 用 <code>255.255.255.255</code>（有限广播，本网段所有设备）；</li><li>目的 MAC 用 <code>FF:FF:FF:FF:FF:FF</code>。</li></ul><p>这三个值分别对应 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0119ba6c38b7d.html">LV010</a> 第三节里提到的 <code>0.0.0.0/8</code>，以及 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb01bacb81dfb86.html">LV030</a> 第三节里的广播地址。也就是说，<strong>ARP 与广播机制才是 DHCP 能起步的前提</strong>。</p><p>从这个角度看协议栈的依赖顺序很清楚：链路层收发包 → ARP / IP → UDP → DHCP，一层都不能跳。</p><h2 id="三、-dora-四步交互" tabindex="-1">三、 DORA 四步交互 <a class="header-anchor" href="#三、-dora-四步交互" aria-label="Permalink to &quot;三、 DORA 四步交互&quot;">​</a></h2><h3 id="_1-四步各自做什么" tabindex="-1">1. 四步各自做什么 <a class="header-anchor" href="#_1-四步各自做什么" aria-label="Permalink to &quot;1. 四步各自做什么&quot;">​</a></h3><p>这四个步骤合称 <strong>DORA</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>名称</th><th>方向</th><th>内容</th></tr></thead><tbody><tr><td>1</td><td>DISCOVER（发现）</td><td>客户端 → <strong>广播</strong></td><td>&quot;本网段有没有 DHCP 服务器？我需要一个地址&quot;</td></tr><tr><td>2</td><td>OFFER（提供）</td><td>服务器 → 客户端</td><td>&quot;我这有个 <code>192.168.16.100</code>，要不要&quot;</td></tr><tr><td>3</td><td>REQUEST（请求）</td><td>客户端 → <strong>广播</strong></td><td>&quot;我选定 <code>192.168.16.100</code> 了&quot;</td></tr><tr><td>4</td><td>ACK（确认）</td><td>服务器 → 客户端</td><td>&quot;准了，租给你 24 小时&quot;，同时给出掩码、网关、DNS</td></tr></tbody></table><img src="'+r+'" alt="DHCP 的 DORA 四步交互与租约"><h3 id="_2-第-3-步为什么还要广播" tabindex="-1">2. 第 3 步为什么还要广播 <a class="header-anchor" href="#_2-第-3-步为什么还要广播" aria-label="Permalink to &quot;2. 第 3 步为什么还要广播&quot;">​</a></h3><p>有一个细节常被问：<strong>第 3 步为什么还要广播？</strong></p><p>因为网络里可能有多台 DHCP 服务器，第 2 步它们可能都给了 OFFER。客户端选定其中一个后，必须广播一声让<strong>落选的那些把候选地址收回去</strong>，否则那些地址就被白白占住了。</p><h3 id="_3-第-4-步之后的补充动作" tabindex="-1">3. 第 4 步之后的补充动作 <a class="header-anchor" href="#_3-第-4-步之后的补充动作" aria-label="Permalink to &quot;3. 第 4 步之后的补充动作&quot;">​</a></h3><p>第 4 步之后，客户端还会用 ARP 检查一下这个地址有没有被占用（免费 ARP，见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb01bacb81dfb86.html">LV030</a> 第五节），确认没冲突才正式启用。这一步在实验室里遇到&quot;地址冲突&quot;告警时值得留个心眼。</p><h2 id="四、-租约与续租" tabindex="-1">四、 租约与续租 <a class="header-anchor" href="#四、-租约与续租" aria-label="Permalink to &quot;四、 租约与续租&quot;">​</a></h2><h3 id="_1-dhcp-给的不只是一串-ip" tabindex="-1">1. DHCP 给的不只是一串 IP <a class="header-anchor" href="#_1-dhcp-给的不只是一串-ip" aria-label="Permalink to &quot;1. DHCP 给的不只是一串 IP&quot;">​</a></h3><p>一次 ACK 里会带回一整套参数，这正是&quot;插上网线就能上网&quot;的原因：</p><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td>IP 地址</td><td>自己的地址</td></tr><tr><td>子网掩码</td><td>判断同网段</td></tr><tr><td>默认网关</td><td>跨网段时的第一站（见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0267db3a1c4e8.html">LV015</a>）</td></tr><tr><td>DNS 服务器</td><td>域名 → IP 的解析服务器</td></tr><tr><td>租约时长</td><td>这个地址能用多久</td></tr></tbody></table><p>一次拿到全部参数，这正是 DHCP 相比&quot;手工填四个框&quot;的最大价值：<strong>它不只分配地址，还顺带把&quot;这个网络该怎么走&quot;一起告诉了你。</strong></p><h3 id="_2-t1、t2-与租期" tabindex="-1">2. T1、T2 与租期 <a class="header-anchor" href="#_2-t1、t2-与租期" aria-label="Permalink to &quot;2. T1、T2 与租期&quot;">​</a></h3><p>DHCP 分配的地址是<strong>租</strong>给你的，不是永久给你：</p><table tabindex="0"><thead><tr><th>时间点</th><th>动作</th></tr></thead><tbody><tr><td>到租期的 50%（T1）</td><td>客户端单播给原服务器请求续租</td></tr><tr><td>到租期的 87.5%（T2）</td><td>如果还没续上，广播找任意服务器</td></tr><tr><td>租期到</td><td>必须停止使用该地址</td></tr></tbody></table><p>这样做的目的是：设备离开网络后，地址能被回收再分配给别人，不至于浪费。</p><p>两个时间点的设计意图也不一样：<strong>T1 是&quot;优先找原服务器&quot;</strong>（保持地址稳定），<strong>T2 是&quot;保底求助&quot;</strong>（先保证不断网，哪怕换个服务器）。</p><h2 id="五、-本工程为什么不用-dhcp" tabindex="-1">五、 本工程为什么不用 DHCP <a class="header-anchor" href="#五、-本工程为什么不用-dhcp" aria-label="Permalink to &quot;五、 本工程为什么不用 DHCP&quot;">​</a></h2><h3 id="_1-三条理由" tabindex="-1">1. 三条理由 <a class="header-anchor" href="#_1-三条理由" aria-label="Permalink to &quot;1. 三条理由&quot;">​</a></h3><p>这不是&quot;实现不了&quot;，而是<strong>故意不要</strong>，原因有三层：</p><p>（1）<strong>内存预算紧</strong>。本工程 <code>lwipopts.h</code> 里 <code>MEM_SIZE</code> 只有 8 KB、<code>PBUF_POOL_SIZE</code> 只有 8 个，DHCP 需要额外的状态机与报文缓冲，而 <code>LWIP_DHCP</code> 宏被显式关掉了（<code>dhcp.c</code> 虽然编进工程，但被宏裁成了空实现）。</p><p>（2）<strong>地址必须可预测</strong>。Bootloader 的升级流程是&quot;PC 上的脚本主动去连板子&quot;，脚本里写死了 <code>192.168.16.30</code>。如果地址是 DHCP 随机分配的，脚本根本不知道该连谁——<strong>这是嵌入式升级场景里最实际的理由</strong>。</p><p>（3）<strong>不需要长期在线</strong>。DHCP 的价值在&quot;设备频繁加入离开的网络&quot;。而这块板子是&quot;插上线、升级、跳转 APP&quot;，全程几分钟，静态地址更简单可靠。</p><h3 id="_2-产品里的常见做法" tabindex="-1">2. 产品里的常见做法 <a class="header-anchor" href="#_2-产品里的常见做法" aria-label="Permalink to &quot;2. 产品里的常见做法&quot;">​</a></h3><p>那产品里怎么做？常见组合是**&quot;静态地址 + 存到非易失存储&quot;**：默认给一个出厂地址，需要改的时候由上位机下发新地址，写进外部 SPI Flash（本工程的 <code>paramset</code> / <code>paramget</code> 命令与 W25Q128 驱动就是为这类需求准备的）。</p><p>这条路线保留了静态地址&quot;可预测&quot;的优点，又避免了&quot;改地址要重新编译烧录&quot;的缺点。</p><h3 id="_3-169-254-地址-dhcp-失败的标志" tabindex="-1">3. 169.254 地址：DHCP 失败的标志 <a class="header-anchor" href="#_3-169-254-地址-dhcp-失败的标志" aria-label="Permalink to &quot;3. 169.254 地址：DHCP 失败的标志&quot;">​</a></h3><p>如果 PC 设成了&quot;自动获取 IP&quot;，而网络里<strong>根本没有 DHCP 服务器</strong>，PC 会退而求其次，自己挑一个 <code>169.254.x.x</code> 用（叫链路本地地址，Windows 上会提示&quot;受限制的连接&quot;）。</p><p>这个地址段在同一链路上靠 ARP 还能互相通信，但<strong>不可路由</strong>（出不了本网段）。</p><p>排错意义很大：<strong>只要看到 PC 拿到 169.254 开头的地址，就说明&quot;地址没配好&quot;，此时去 ping 板子必然不通</strong>——不用再看网线、交换机，直接回去手工填一个同网段 IP 即可。</p><h2 id="六、-小结与参考资料" tabindex="-1">六、 小结与参考资料 <a class="header-anchor" href="#六、-小结与参考资料" aria-label="Permalink to &quot;六、 小结与参考资料&quot;">​</a></h2><h3 id="_1-本篇小结" tabindex="-1">1. 本篇小结 <a class="header-anchor" href="#_1-本篇小结" aria-label="Permalink to &quot;1. 本篇小结&quot;">​</a></h3><ul><li>IP 可以静态配置，也可以由 DHCP 自动分配；本工程用静态，理由是内存紧张、地址要可预测、不需要长期在线。</li><li>DHCP 是应用层协议，跑在 UDP 上（服务器 67 / 客户端 68），起步时用 <code>0.0.0.0</code> 和 <code>255.255.255.255</code> 绕开&quot;没有 IP&quot;的死循环。</li><li>DORA 四步：DISCOVER → OFFER → REQUEST → ACK；REQUEST 要广播是为了让落选的服务器回收地址。</li><li>DHCP 顺带下发掩码、网关、DNS；地址是&quot;租&quot;的，T1 找原服务器续租、T2 广播兜底。</li><li>PC 拿到 <code>169.254.x.x</code> 就是 DHCP 失败的标志，也是排查的起点。</li><li>本工程 <code>LWIP_DHCP = 0</code>，<code>dhcp.c</code> 被宏裁成空实现，仅作源码对照。</li></ul><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>本工程网络配置（静态宏）：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/port/lwip_comm.h" target="_blank" rel="noreferrer"><code>lwip_comm.h</code></a></li><li>协议栈裁剪（<code>LWIP_DHCP = 0</code>）：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/port/lwipopts.h" target="_blank" rel="noreferrer"><code>lwipopts.h</code></a></li><li>DHCP 源码（被宏裁空，可作对照阅读）：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/src/core/ipv4/dhcp.c" target="_blank" rel="noreferrer"><code>dhcp.c</code></a></li><li>手册：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/10-lwIP/STM32F1%20LWIP%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C%28DM9000%E7%89%88%29_V1.1.pdf" target="_blank" rel="noreferrer"><code>STM32F1 LWIP开发手册(DM9000版)_V1.1.pdf</code></a> 第 1.4 节</li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',60)])])}const b=o(c,[["render",l]]);export{P as __pageData,b as default};
